/////////////////////////////////
// cp_mtime_write
//   Write mtime and read back time if supported
/////////////////////////////////
#ifdef RVMODEL_MTIME_ADDRESS
  LI(x13, 42)        # value to write to mtime
  LA(x14, RVMODEL_MTIME_ADDRESS)        # load address of mtime
  SREG x13, 0(x14)        # write mtime = 42 using memory-mapped I/O
  fence o, i        # order the mtime write before the time read
Sm_mcsr_cg_cp_mtime_write:
  csrr x14, time        # read time
  sub x14, x14, x13          # difference should be small
  sltiu x14, x14, 100          # signature is 1 only if time is within 100 above the written value
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, Sm_mcsr_cg_cp_mtime_write, Sm_mcsr_cg_cp_mtime_write_str)

#if __riscv_xlen == 32
  LI(x13, 67)        # value to write to mtimeh
  LA(x14, RVMODEL_MTIME_ADDRESS)        # load address of mtimeh
  SREG x13, 4(x14)        # write mtimeh = 67 using memory-mapped I/O
  fence o, i        # order the mtimeh write before the timeh read
Sm_mcsr_cg_cp_mtime_write_h:
  csrr x14, timeh        # read timeh
  sub x14, x14, x13          # difference should be zero
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, Sm_mcsr_cg_cp_mtime_write_h, Sm_mcsr_cg_cp_mtime_write_h_str)
