/////////////////////////////////
// cp_mcycle_wraparound
//   Write max value to mcycle and verify it wraps around cleanly
/////////////////////////////////
  LI(x9, -1)                    # Load all-ones
#if __riscv_xlen == 32
  csrw mcycleh, x9             # Set upper 32 bits of mcycle to maximum (RV32 only)
#endif
Sm_mcsr_cg_cp_mcycle_wraparound_mcycle_wrap:
  csrw mcycle, x9             # Set mcycle to its maximum value
  LI(x14, 100)                # Wait loop for counter ticks
1:
  nop
  addi x14, x14, -1
  bnez x14, 1b
  csrr x13, mcycle               # Read mcycle after the bounded wait
  sltiu x13, x13, 1000       # Pass if mcycle wrapped to a small value
#if __riscv_xlen == 32
  csrr x6, mcycleh             # Read upper 32 bits after the bounded wait
  sltiu x6, x6, 1        # Pass if upper 32 bits wrapped to zero
  and x13, x13, x6    # Pass only if both wraparound conditions are met
#endif
  # Check if x13 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x13, Sm_mcsr_cg_cp_mcycle_wraparound_mcycle_wrap, Sm_mcsr_cg_cp_mcycle_wraparound_mcycle_wrap_str)



/////////////////////////////////
// cp_minstret_wraparound
//   Write max value to minstret and verify it wraps around cleanly
/////////////////////////////////
  LI(x9, -1)                    # Load all-ones
#if __riscv_xlen == 32
  csrw minstreth, x9           # Set upper 32 bits of minstret to maximum (RV32 only)
#endif
Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap:
  csrw minstret, x9            # Set minstret to its maximum value
  nop
  csrr x13, minstret             # Read minstret after wraparound
#if __riscv_xlen == 32
  csrr x6, minstreth           # Read upper 32 bits after wraparound
#endif
  # Check if x13 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x13, Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap, Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap_str)
#if __riscv_xlen == 32
  # Check if x6 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x6, Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap, Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap_str)
#endif



/////////////////////////////////
// cp_mtime_wraparound
//   Write all-ones to memory-mapped mtime and verify it wraps around cleanly
/////////////////////////////////
#ifdef RVMODEL_MTIME_ADDRESS
  LA(x9, RVMODEL_MTIME_ADDRESS) # base address of mtime
  LI(x13, -1)                     # all-ones
#if __riscv_xlen == 32
  SREG x13, 4(x9)          # write all-ones to the upper half (RV32 only)
#endif
Sm_mcsr_cg_cp_mtime_wraparound_mtime_wrap:
  SREG x13, 0(x9)          # write all-ones to the base word; arms the counter
  LI(x14, 100000)            # wrap threshold; too big for an sltiu immediate (12-bit signed)
  LI(x13, 20000)                 # bounded poll iterations (models tick mtime at different rates)
1:
  LREG x6, 0(x9)         # read raw lower half
  bltu x6, x14, 2f     # wrapped to a small value -> done
  addi x13, x13, -1
  bnez x13, 1b
2:
  sltu x13, x6, x14  # pass if mtime wrapped to a small value
#if __riscv_xlen == 32
  LREG x6, 4(x9)         # read raw upper half after the bounded wait
  sltiu x6, x6, 1         # pass if upper half wrapped to zero
  and x13, x13, x6     # pass only if both halves wrapped
#endif
  # Check if x13 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x13, Sm_mcsr_cg_cp_mtime_wraparound_mtime_wrap, Sm_mcsr_cg_cp_mtime_wraparound_mtime_wrap_str)
#endif


